struct UiState { int count = 0; bool loading = false; };
using Intent = std::variant<Increment, Refresh, LoadFailed>;
UiState reduce(const UiState& s, const Intent& i) {
  return std::visit(overloaded{
      [&](const Increment&) { auto n = s; ++n.count; return n; },
      [&](const Refresh&)   { auto n = s; n.loading = true; return n; },
      [&](const LoadFailed& f) { auto n = s; n.loading = false; return n; },
    }, i);
}
